versions.variantCss:
.wemd-callout-pro[data-variant="bytedance-callout-pro"] {
  background: var(--wemd-bg-card);
  border-radius: var(--wemd-border-radius);
  padding: 20px 24px;
  margin: 16px 0;
  border: 1px solid var(--wemd-border);
  border-left: 4px solid var(--wemd-secondary);
  box-shadow: var(--wemd-shadow);
}
.wemd-callout-pro[data-variant="bytedance-callout-pro"] .wemd-component-body {
  padding: 0;
}
.wemd-callout-pro[data-variant="bytedance-callout-pro"] .wemd-component-body .wemd-child-1 {
  color: var(--wemd-secondary);
  font-size: 14px;
  font-weight: 700;
  margin: 0 0 6px 0;
}
.wemd-callout-pro[data-variant="bytedance-callout-pro"] .wemd-component-body .wemd-child-2 {
  color: var(--wemd-text-normal);
  font-size: 14px;
  line-height: 1.7;
  margin: 0 0 8px 0;
}
.wemd-callout-pro[data-variant="bytedance-callout-pro"] .wemd-component-body .wemd-child-3 {
  color: var(--wemd-text-soft);
  font-size: 13px;
  margin: 0;
}
